  "components/card/overview": {
    "content": {
      "component": "Page",
      "props": {
        "title": "Card",
        "description": "The filled or bordered box the panels in a layout are built from. It is a container rather than a control, so its padding is uniform and comes off the spacing scale instead of the control scale, and it stays out of the shared state machine — a panel that washed under the pointer would read as something you can press.",
      },
      "children": [
        {
          "component": "Section",
          "props": {
            "title": "Variants",
            "description": "Only `tinted` reads the tint; the rest resolve against the neutral surface and border roles. `raised` is a panel on the canvas, `sunken` a well inside one, `outlined` a boundary with no fill of its own.",
          },
          "children": [
            {
              "component": "Grid",
              "props": {"min": 224},
              "children": [
                {
                  "component": "Card",
                  "props": {"variant": "raised"},
                  "children": [
                    {
                      "component": "SectionLabel",
                      "children": ["raised"],
                    },
                    {
                      "component": "Inline",
                      "children": [
                        "Padding, gap, and radius all come from the size.",
                      ],
                    },
                  ],
                },
                {
                  "component": "Card",
                  "props": {"variant": "sunken"},
                  "children": [
                    {
                      "component": "SectionLabel",
                      "children": ["sunken"],
                    },
                    {
                      "component": "Inline",
                      "children": [
                        "Padding, gap, and radius all come from the size.",
                      ],
                    },
                  ],
                },
                {
                  "component": "Card",
                  "props": {"variant": "outlined"},
                  "children": [
                    {
                      "component": "SectionLabel",
                      "children": ["outlined"],
                    },
                    {
                      "component": "Inline",
                      "children": [
                        "Padding, gap, and radius all come from the size.",
                      ],
                    },
                  ],
                },
                {
                  "component": "Card",
                  "props": {"variant": "tinted"},
                  "children": [
                    {
                      "component": "SectionLabel",
                      "children": ["tinted"],
                    },
                    {
                      "component": "Inline",
                      "children": [
                        "Padding, gap, and radius all come from the size.",
                      ],
                    },
                  ],
                },
              ],
            },
          ],
        },
        {
          "component": "Section",
          "props": {
            "title": "Tints",
            "description": "The tinted variant across every ramp: a 50 fill under a 200 border. The other three ignore `tint` entirely, so setting it on them is harmless and does nothing.",
          },
          "children": [
            {
              "component": "Grid",
              "props": {"min": 160},
              "children": [
                {
                  "component": "Card",
                  "props": {
                    "size": "small",
                    "tint": "primary",
                    "variant": "tinted",
                  },
                  "children": [
                    {
                      "component": "SectionLabel",
                      "props": {"tint": "primary"},
                      "children": ["primary"],
                    },
                  ],
                },
                {
                  "component": "Card",
                  "props": {
                    "size": "small",
                    "tint": "neutral",
                    "variant": "tinted",
                  },
                  "children": [
                    {
                      "component": "SectionLabel",
                      "props": {"tint": "neutral"},
                      "children": ["neutral"],
                    },
                  ],
                },
                {
                  "component": "Card",
                  "props": {
                    "size": "small",
                    "tint": "info",
                    "variant": "tinted",
                  },
                  "children": [
                    {
                      "component": "SectionLabel",
                      "props": {"tint": "info"},
                      "children": ["info"],
                    },
                  ],
                },
                {
                  "component": "Card",
                  "props": {
                    "size": "small",
                    "tint": "success",
                    "variant": "tinted",
                  },
                  "children": [
                    {
                      "component": "SectionLabel",
                      "props": {"tint": "success"},
                      "children": ["success"],
                    },
                  ],
                },
                {
                  "component": "Card",
                  "props": {
                    "size": "small",
                    "tint": "warning",
                    "variant": "tinted",
                  },
                  "children": [
                    {
                      "component": "SectionLabel",
                      "props": {"tint": "warning"},
                      "children": ["warning"],
                    },
                  ],
                },
                {
                  "component": "Card",
                  "props": {
                    "size": "small",
                    "tint": "danger",
                    "variant": "tinted",
                  },
                  "children": [
                    {
                      "component": "SectionLabel",
                      "props": {"tint": "danger"},
                      "children": ["danger"],
                    },
                  ],
                },
              ],
            },
          ],
        },
        {
          "component": "Section",
          "props": {
            "title": "Sizes",
            "description": "Padding, the gap between children, and the radius step together. Each step is a spacing token and a radius token, not a control profile — a card holds content rather than sitting in a row of controls.",
          },
          "children": [
            {
              "component": "Stack",
              "children": [
                {
                  "component": "Specimen",
                  "props": {"label": "small"},
                  "children": [
                    {
                      "component": "Box",
                      "props": {"width": 256},
                      "children": [
                        {
                          "component": "Card",
