                  "props": {"label": "large"},
                  "children": [
                    {
                      "component": "Box",
                      "props": {"width": 256},
                      "children": [
                        {
                          "component": "Card",
                          "props": {"size": "large"},
                          "children": [
                            {
                              "component": "SectionLabel",
                              "children": ["Quality"],
                            },
                            {
