  "components/divider/overview": {
    "content": {
      "component": "Page",
      "props": {
        "title": "Divider",
        "description": "A one-pixel rule. It carries no component tokens of its own: a separator is entirely described by a border colour and the hairline step of the spacing scale, and inventing `divider-*` aliases for those would only add a layer to read through.",
      },
      "children": [
        {
          "component": "Section",
          "props": {
            "title": "Tones",
            "description": "The two border roles. `muted` is the lighter of the pair, for a rule inside a filled surface where the default would cut too hard; `default` is what separates one region from another.",
          },
          "children": [
            {
              "component": "Stack",
              "children": [
                {
                  "component": "Specimen",
                  "props": {"label": "default"},
                  "children": [
                    {
                      "component": "Box",
                      "props": {"grow": true},
                      "children": [
                        {"component": "Divider"},
                      ],
                    },
                  ],
                },
                {
                  "component": "Specimen",
                  "props": {"label": "muted"},
                  "children": [
                    {
                      "component": "Box",
                      "props": {"grow": true},
                      "children": [
                        {
                          "component": "Divider",
                          "props": {"tone": "muted"},
                        },
                      ],
                    },
                  ],
                },
              ],
            },
          ],
        },
        {
          "component": "Section",
          "props": {
            "title": "Vertical",
            "description": "Stretches to its flex parent, so a toolbar row sizes it without a height being passed in. That is the whole reason it is a div rather than an `<hr>`: a rule that has to be told how tall it is will be told wrong somewhere.",
          },
          "children": [
            {
              "component": "Stack",
              "children": [
                {
                  "component": "Specimen",
                  "props": {"label": "labels"},
                  "children": [
                    {
                      "component": "Inline",
                      "children": ["Source"],
                    },
                    {
                      "component": "Divider",
                      "props": {"orientation": "vertical"},
                    },
                    {
                      "component": "Inline",
                      "children": ["Target"],
                    },
                    {
                      "component": "Divider",
                      "props": {"orientation": "vertical"},
                    },
                    {
                      "component": "Inline",
                      "children": ["Glossary"],
                    },
                  ],
                },
                {
                  "component": "Specimen",
                  "props": {"label": "toolbar"},
                  "children": [
                    {
                      "component": "ActionBar",
                      "children": [
                        {
                          "component": "Button",
                          "props": {"size": "small", "variant": "plain"},
                          "children": ["Undo"],
                        },
