  "components/keycap/overview": {
    "content": {
      "component": "Page",
      "props": {
        "title": "KeyCap",
        "description": "One key, drawn three ways. It reads the theme's ink and surface roles directly and takes no tint — a key looks like a key whatever is around it. A cap says what the key *is*; where the key can be changed, that is a ShortcutRecorder instead.",
      },
      "children": [
        {
          "component": "Section",
          "props": {
            "title": "Variants",
            "description": "`hint` — the default — is bare faint text in the display cut: the `⌘F` beside an empty search field, the `⌥2` in a card's corner, an aside the eye may skip. `strong` is the same a step darker, for a hint that has to survive on a busy row. `key` alone draws the cap — a recessed, chip-cornered fill with no border, since a key is pressed *into* the surface rather than raised off it — and is what a settings page lists shortcuts in.",
          },
          "children": [
            {
              "component": "Stack",
              "children": [
                {
                  "component": "Specimen",
                  "props": {"label": "hint"},
                  "children": [
                    {
                      "component": "KeyCap",
                      "props": {"variant": "hint"},
                      "children": ["⌥2"],
                    },
                  ],
                },
                {
                  "component": "Specimen",
                  "props": {"label": "strong"},
                  "children": [
                    {
                      "component": "KeyCap",
                      "props": {"variant": "strong"},
                      "children": ["⌘K"],
                    },
                  ],
                },
                {
                  "component": "Specimen",
                  "props": {"label": "key"},
                  "children": [
                    {
                      "component": "KeyCap",
                      "props": {"variant": "key"},
                      "children": ["⌘⇧T"],
                    },
                  ],
                },
              ],
            },
          ],
        },
        {
          "component": "Section",
          "props": {
            "title": "Sizes",
            "description": "Colours are shared across the three; only the type steps, and only at the top — `small` and `medium` set the same face, `large` goes one up. Pick the size from what the key sits beside: `small` next to body text, `medium` in a row of controls.",
          },
          "children": [
            {
              "component": "Stack",
              "children": [
                {
                  "component": "Specimen",
                  "props": {"label": "small"},
                  "children": [
                    {
                      "component": "KeyCap",
                      "props": {"size": "small"},
                      "children": ["⌘K"],
                    },
                    {
                      "component": "KeyCap",
                      "props": {"size": "small", "variant": "strong"},
                      "children": ["⌘K"],
                    },
                    {
                      "component": "KeyCap",
                      "props": {"size": "small", "variant": "key"},
                      "children": ["⌘"],
                    },
                    {
                      "component": "KeyCap",
                      "props": {"size": "small", "variant": "key"},
                      "children": ["⇧"],
                    },
                    {
                      "component": "KeyCap",
                      "props": {"size": "small", "variant": "key"},
                      "children": ["K"],
                    },
                    {
                      "component": "KeyCap",
                      "props": {"size": "small", "variant": "key"},
                      "children": ["Esc"],
                    },
                  ],
                },
                {
                  "component": "Specimen",
                  "props": {"label": "medium"},
                  "children": [
                    {
                      "component": "KeyCap",
                      "props": {"size": "medium"},
                      "children": ["⌘K"],
                    },
                    {
                      "component": "KeyCap",
                      "props": {"size": "medium", "variant": "strong"},
                      "children": ["⌘K"],
                    },
                    {
                      "component": "KeyCap",
                      "props": {"size": "medium", "variant": "key"},
                      "children": ["⌘"],
                    },
                    {
                      "component": "KeyCap",
                      "props": {"size": "medium", "variant": "key"},
                      "children": ["⇧"],
                    },
                    {
                      "component": "KeyCap",
                      "props": {"size": "medium", "variant": "key"},
                      "children": ["K"],
                    },
                    {
                      "component": "KeyCap",
                      "props": {"size": "medium", "variant": "key"},
                      "children": ["Esc"],
                    },
                  ],
                },
                {
                  "component": "Specimen",
                  "props": {"label": "large"},
                  "children": [
                    {
                      "component": "KeyCap",
                      "props": {"size": "large"},
                      "children": ["⌘K"],
                    },
                    {
                      "component": "KeyCap",
                      "props": {"size": "large", "variant": "strong"},
                      "children": ["⌘K"],
                    },
                    {
                      "component": "KeyCap",
                      "props": {"size": "large", "variant": "key"},
                      "children": ["⌘"],
                    },
                    {
                      "component": "KeyCap",
                      "props": {"size": "large", "variant": "key"},
                      "children": ["⇧"],
                    },
                    {
                      "component": "KeyCap",
                      "props": {"size": "large", "variant": "key"},
                      "children": ["K"],
                    },
                    {
                      "component": "KeyCap",
                      "props": {"size": "large", "variant": "key"},
                      "children": ["Esc"],
                    },
                  ],
                },
              ],
            },
          ],
        },
        {
          "component": "Section",
          "props": {
            "title": "Chords",
            "description": "A chord is several caps composed by the caller, which keeps the separator the caller's decision: macOS sets its modifiers flush, a cross-platform app usually wants a `+` between them. A hint sets the whole chord in one cap — `⌘⇧K` is one glyph run, not three — and the cap sits on the text baseline it is set in, so a sentence naming a shortcut does not gain a line of leading.",
          },
          "children": [
            {
              "component": "Stack",
              "children": [
                {
                  "component": "Specimen",
                  "props": {"label": "flush"},
                  "children": [
                    {
                      "component": "KeyCap",
                      "props": {"size": "small", "variant": "key"},
                      "children": ["⌘"],
                    },
                    {
                      "component": "KeyCap",
                      "props": {"size": "small", "variant": "key"},
                      "children": ["⇧"],
                    },
                    {
                      "component": "KeyCap",
                      "props": {"size": "small", "variant": "key"},
                      "children": ["K"],
                    },
                  ],
                },
                {
                  "component": "Specimen",
                  "props": {"label": "joined"},
                  "children": [
                    {
                      "component": "Box",
                      "props": {
                        "display": "inline-flex",
                        "gap": "spacing.1",
                        "align": "center",
                        "tone": "muted",
                      },
                      "children": [
                        {
                          "component": "KeyCap",
                          "props": {"size": "small", "variant": "key"},
                          "children": ["Ctrl"],
                        },
                        "+",
                        {
                          "component": "KeyCap",
                          "props": {"size": "small", "variant": "key"},
                          "children": ["Shift"],
                        },
                        "+",
                        {
                          "component": "KeyCap",
                          "props": {"size": "small", "variant": "key"},
                          "children": ["P"],
                        },
                      ],
                    },
                  ],
                },
                {
                  "component": "Specimen",
                  "props": {"label": "as a hint"},
                  "children": [
                    {
                      "component": "KeyCap",
                      "props": {"size": "small"},
                      "children": ["⌘⇧K"],
                    },
                  ],
                },
                {
                  "component": "Specimen",
                  "props": {"label": "in prose"},
                  "children": [
                    {
                      "component": "Inline",
                      "children": [
                        "Open the command palette with ",
                        {
                          "component": "KeyCap",
                          "props": {"size": "small"},
                          "children": ["⌘K"],
                        },
                        ", then type a document name.",
                      ],
                    },
                  ],
                },
              ],
            },
          ],
