  "components/progress/live": {
    "state": {"value": 8},
    "timers": [
      {
        "every": 400,
        "set": "value",
        "value": {
          "if": {
            "gte": [
              {"state": "value"},
              100,
            ],
          },
          "then": 0,
          "else": {
            "add": [
              {"state": "value"},
              4,
            ],
          },
        },
      },
    ],
    "content": {
      "component": "Box",
      "props": {"width": 416},
      "children": [
        {
          "component": "Progress",
          "id": "progress",
          "derive": {
            "value": {"state": "value"},
          },
        },
      ],
    },
    "checkpoints": [
      {
        "id": "initial",
        "steps": [],
        "expect": {"value": 8},
      },
      {
        "id": "tick",
        "steps": [
          {"action": "advance", "milliseconds": 400},
        ],
        "expect": {"value": 12},
      },
      {
        "id": "finished",
        "steps": [
          {"action": "advance", "milliseconds": 9200},
        ],
        "expect": {"value": 100},
      },
      {
        "id": "wrapped",
        "steps": [
          {"action": "advance", "milliseconds": 9600},
        ],
        "expect": {"value": 0},
      },
    ],
    "id": "components-progress--live",
    "title": "Components/Progress",
    "name": "Live",
    "layout": "centered",
  },
